#!/bin/bash
# Kerrian as a 3D cartoon fighter, made with the Codex CLI (macOS, the one inside ChatGPT.app) from frames of his video
# (tools/art/friends/kerrian/*.jpg, private, never published). Same prompt pattern as tools/art/friends.ps1.
#   bash tools/art/kerrian.sh          -> tools/art/apose/kerrian.png (Pixar-like base, kept in friends/kerrian/base_pixar.png)
#   bash tools/art/kerrian.sh restyle  -> the same design redrawn in the Smash Bros / MultiVersus style (kept in friends/kerrian/base_smash.png)
#   bash tools/art/kerrian.sh outfit   -> baggier trousers, short-sleeve jacket, simpler cartoon head (kept in friends/kerrian/base_jacket.png)
#   bash tools/art/kerrian.sh vest     -> the jacket replaced by a black sleeveless cargo vest (kept in friends/kerrian/base_vest.png)
#   bash tools/art/kerrian.sh beard    -> a lighter, scruffier beard (the approved design, kept in friends/kerrian/final_design.png)
#   bash tools/art/kerrian.sh views    -> that design straight from the front and from the back, in T-pose, without the glasses
#                                         (made in code), for Meshy multi-image to 3D: tools/art/apose/kerrian_front.png, kerrian_back.png
#   (if Codex fails to save it: python3 tools/art/codex_recover.py tools/art/apose kerrian)
cd "$(dirname "$0")/../.."
EXE=/Applications/ChatGPT.app/Contents/Resources/codex-cli/bin/codex
PH=tools/art/friends/kerrian
if [ "$1" = views ]; then
  ffmpeg -v error -i "$PH/final_design.png" -vf "crop=380:400:310:10,scale=760:-1" -y "$PH/final_head.png"
  COMMON='Image 1 is the APPROVED design of this fighter: keep EVERYTHING of it exactly (face and likeness, green eyes, eyebrows, nose, scruffy light beard, hair, big head, short neck, the black sleeveless cargo vest, the mustard yellow t-shirt and its black print, the very baggy white trousers, the brown mountain boots with red laces, the art style, the colours). Images 2 and 3 are photos of the real person, for the likeness. This picture is the input of an image-to-3D tool, so: NO GLASSES at all (they are added later), the eyes fully visible; a clean symmetric T-POSE, arms straight out to the sides at shoulder height, palms facing down, fingers together and straight, legs straight and slightly apart, feet flat; orthographic-looking camera at chest height, no perspective distortion; the whole body from the top of the hair to the soles, centred, filling 90% of the height; flat even studio lighting with no strong shadows and no rim light; plain light grey background, no cast shadow, no text, no logo, no watermark. Portrait 1024x1536.'
  "$EXE" exec --skip-git-repo-check -s workspace-write -C tools/art/apose "Use your image generation tool. Create ONE new image. $COMMON Image 4 is a close-up of the approved face: the head must be the SAME face as image 4, same age (around 30), same proportions, same calm deadpan half-lidded look with relaxed eyebrows (NOT frowning, not angry, not younger), same long face, same nose, same scruffy beard, only without the glasses and seen straight from the front. Seen EXACTLY from the FRONT (0 degrees, facing the camera, no three-quarter turn). Save it as kerrian_front.png in the current directory and do not resize it." -i "$PH/final_design.png" -i "$PH/face_front.png" -i "$PH/face_profile.png" -i "$PH/final_head.png" < /dev/null 2>/dev/null | tail -2
  "$EXE" exec --skip-git-repo-check -s workspace-write -C tools/art/apose "Use your image generation tool. Create ONE new image. $COMMON Seen EXACTLY from the BACK (180 degrees): the back of the head with the longer hair covering the nape, the plain back of the vest, the back of the trousers and the heels of the boots; the same T-pose seen from behind. Image 4 is the front view of the same picture: match it exactly in pose, scale and position. Save it as kerrian_back.png in the current directory and do not resize it." -i "$PH/final_design.png" -i "$PH/face_back.png" -i "$PH/face_profile.png" -i tools/art/apose/kerrian_front.png < /dev/null 2>/dev/null | tail -2
  ls tools/art/apose/kerrian_front.png tools/art/apose/kerrian_back.png
  exit
fi
if [ "$1" = beard ]; then
  R='Create ONE new image, portrait 1024x1536. Image 1 is the final design of this fighter: keep EVERYTHING of it exactly (face, head shape, hair, glasses, black cargo vest, mustard yellow t-shirt and its print, baggy white trousers, brown boots with red laces, art style, colours, A-pose, framing, plain background). Make ONE change: the beard is LESS DENSE and LESS GROOMED, like in images 2 and 3: a sparse, scruffy, uneven short stubble beard along the jaw and the chin, thinner on the cheeks where the skin shows through, soft irregular edges (no sharp trimmed outline, no neat sculpted shape), a thin patchy moustache, a small soul patch under the lower lip. Still stylised like the rest of the character. No text, no logo, no watermark. Save it as kerrian.png in the current directory and do not resize it.'
  "$EXE" exec --skip-git-repo-check -s workspace-write -C tools/art/apose "Use your image generation tool. $R" -i "$PH/base_vest.png" -i "$PH/face_front.png" -i "$PH/face_profile.png" < /dev/null 2>/dev/null | tail -3
  [ -f tools/art/apose/kerrian.png ] && echo "OK kerrian" || echo "MISSING kerrian"
  exit
fi
if [ "$1" = vest ]; then
  R='Create ONE new image, portrait 1024x1536. Image 1 is the current design of this fighter: keep EVERYTHING of it exactly (the face, the head, the hair, the glasses, the mustard yellow t-shirt and its black print, the very baggy white trousers, the brown mountain boots with red laces, the art style, the colours, the A-pose, the framing, the plain light grey background). Make ONE change: replace the light blue short-sleeve denim jacket by a SLEEVELESS black utility cargo vest like the one of image 2, but WITHOUT ANY LOGO, label or patch: matte black technical fabric, a round collarless neckline, a full front zip, worn half open or closed up to the chest so the t-shirt print still shows at the top, two flap chest pockets, two big boxy lower cargo pockets with flaps and zips, a small pocket on the shoulder, a little metal D-ring; the yellow t-shirt sleeves and the bare arms fully visible. No sleeves on the vest, nothing covering the arms. Neutral even studio lighting, no cast shadow, no text, no logo, no watermark. Save it as kerrian.png in the current directory and do not resize it.'
  "$EXE" exec --skip-git-repo-check -s workspace-write -C tools/art/apose "Use your image generation tool. $R" -i "$PH/base_jacket.png" -i "$PH/vest_ref.png" < /dev/null 2>/dev/null | tail -3
  [ -f tools/art/apose/kerrian.png ] && echo "OK kerrian" || echo "MISSING kerrian"
  exit
fi
if [ "$1" = outfit ]; then
  R='Create ONE new image, portrait 1024x1536. Image 1 is the current design of this fighter (Super Smash Bros. Ultimate / MultiVersus style 3D fighting game character): keep its art style, colours, A-pose, framing, plain light grey background, the mustard yellow t-shirt and its black print, and the brown Paraboot style mountain boots with red laces. Images 2 and 3 are photos of the real person (keep him recognisable). Image 4 is only a STYLE reference for the HEAD (Batman: The Animated Series designs by Bruce Timm), nothing else is copied from it. Make exactly three changes: '
  R+='(1) the white trousers become much BAGGIER: very wide skater-style loose white trousers, big soft folds, the hems piled on top of the boots; '
  R+='(2) add a SHORT-SLEEVE JACKET worn OPEN over the t-shirt, layered: a faded light blue denim work jacket with the sleeves ending above the elbow (shorter than or level with the t-shirt sleeves, both visible), a collar, two chest pockets, worn open so the t-shirt print stays visible, hanging straight and not covering the arms; '
  R+='(3) a much SIMPLER cartoon head, like the reference cartoons: few big clean shapes and planes, no skin texture, no pores, no wrinkles; the hair as a few large simple sculpted masses (still a messy fringe on the forehead and longer hair on the nape); the beard and moustache as one simple flat darker shape along the jaw and chin; simple eyebrows as two straight thick shapes; simple green eyes with a calm deadpan half-lidded look; a simple strong nose; still the big head, the short neck and the rimless glasses (two clear lenses, thin silver bridge and temples). He must stay recognisable as the person of images 2 and 3, a 3D game character, not a 2D drawing and not a caricature. '
  R+='Neutral even studio lighting, no cast shadow, no text, no logo, no watermark. Save it as kerrian.png in the current directory and do not resize it.'
  "$EXE" exec --skip-git-repo-check -s workspace-write -C tools/art/apose "Use your image generation tool. $R" -i "$PH/base_smash.png" -i "$PH/face_front.png" -i "$PH/face_profile.png" -i "$PH/style_btas.png" < /dev/null 2>/dev/null | tail -3
  [ -f tools/art/apose/kerrian.png ] && echo "OK kerrian" || echo "MISSING kerrian"
  exit
fi
if [ "$1" = restyle ]; then
  R='Create ONE new image, portrait 1024x1536. Image 1 is the APPROVED design of this fighter: keep EVERYTHING of it (his face and likeness, green eyes, rimless glasses, hair, beard, big head, short neck, the mustard yellow t-shirt and its black print, the wide white trousers, the brown Paraboot style mountain boots with red laces, the A-pose, the framing, the plain light grey background). Images 2 to 4 are photos of the real person, to keep the face recognisable. Change ONLY the art style: redraw him as a playable fighter of Super Smash Bros. Ultimate or MultiVersus, a stylised 3D fighting game character: chunky simplified sculpted shapes, a bold readable silhouette, slightly heroic proportions (strong hands, chunky boots), hand-painted textures with painted highlights and soft gradients instead of realistic materials, clean stylised hair as a few big sculpted locks, crisp edges with a subtle rim light, saturated colours, a game-ready look, confident and a bit cocky expression while staying deadpan. Not photorealistic, not a 2D drawing, not a caricature. Neutral even studio lighting, no cast shadow, no text, no logo, no watermark. Save it as kerrian.png in the current directory and do not resize it.'
  "$EXE" exec --skip-git-repo-check -s workspace-write -C tools/art/apose "Use your image generation tool. $R" -i "$PH/base_pixar.png" -i "$PH/face_front.png" -i "$PH/face_profile.png" -i "$PH/face_back.png" < /dev/null 2>/dev/null | tail -3
  [ -f tools/art/apose/kerrian.png ] && echo "OK kerrian" || echo "MISSING kerrian"
  exit
fi
POSE=' Full body from head to feet, seen from the front with a slight three-quarter turn to the left (about 20 degrees), standing in a clean A-pose: arms straight and raised well away from the body at 45 degrees (the hands at hip height, far from the thighs), hands open and EMPTY with fingers slightly spread, legs straight and slightly apart, feet flat. Nothing held, nothing on the back, the arms are clear of the body and of the hair.'
LOOK=' Stylised 3D cartoon render like a Pixar or Disney animated feature (The Incredibles, Luca), coherent with a remaster of a late-90s console party fighting game: NOT photorealistic, smooth simplified skin without pores or wrinkles, hair and beard as a few chunky sculpted shapes rather than individual strands, soft clean materials, bold readable silhouette, vivid colours. Neutral even studio lighting, plain light grey background, no cast shadow, no text, no letters, no numbers, no logo, no watermark. Centred with a small margin all around, the character fills most of the height.'
P='Create ONE new image, portrait 1024x1536. The real person in the attached photos, remade as a 3D cartoon fighter. Photos 1 to 3 are close-ups of HIS FACE (front, profile, three-quarter back): the face must be clearly RECOGNISABLE as him, this is the priority. Photo 4 is his full body (for the build and the clothes). Photo 5 is ANOTHER CHARACTER OF THE SAME GAME, drawn from another real friend: copy EXACTLY its render style, its level of cartoon stylisation and its proportions (big head, big expressive eyes, short neck, smooth sculpted shapes) so both look like they come from the same game; only borrow the style, not his face, his clothes or his sad mood. Photo 6 is only a light STYLE hint (Batman: The Animated Series designs): clean simplified shapes and confident lines, nothing copied from it, and the face stays friendly and natural, not a caricature. His face: a long face with a strong straight jaw and broad cheekbones; GREEN eyes, slightly heavy lids, a calm deadpan stare; straight thick dark brown eyebrows, nearly horizontal; a long straight nose with a slightly rounded tip; full lips, a neutral closed mouth (no smile); a scruffy short dark brown beard following the jawline and the chin, a thin moustache, a small soul patch under the lower lip, bare skin between the beard and the cheekbones; ears slightly sticking out; RIMLESS glasses: clear oval lenses with no frame, only a thin silver nose bridge and thin silver temples. His hair: medium-length mid brown messy hair, a choppy uneven fringe falling on the forehead in pointed locks, longer and covering the nape at the back (a soft shaggy mullet), the sides over the top of the ears, one stray lock sticking up on top; soft rather than spiky. Proportions: a BIG cartoon head, about 1/5 of the body height, at least as big as in photo 5 (much bigger than a real one, but not a bobblehead), big cartoon eyes behind the glasses, a SHORT neck (the head sits close to the shoulders), slim build, not lanky, slightly big hands. Clothes as in photo 4: a mustard yellow t-shirt with a big black hand-printed line-art graphic on the front (circles with drop-shaped eyes and tangled doodles, as in the photos; plain on the back), loose wide white trousers whose hems rest on the boots, and brown leather mountain boots in the style of Paraboot Avoriaz: ankle-high chunky grained brown leather, round RED laces through metal eyelets and hooks, a thick black notched rubber lug sole with a visible stitched welt.'
PROMPT="Use your image generation tool. ${P}${POSE}${LOOK} Save it as kerrian.png in the current directory and do not resize it."
"$EXE" exec --skip-git-repo-check -s workspace-write -C tools/art/apose "$PROMPT" -i "$PH/face_front.png" -i "$PH/face_profile.png" -i "$PH/face_back.png" -i "$PH/front.jpg" -i tools/art/apose/nymano.png -i "$PH/style_btas.png" < /dev/null 2>/dev/null | tail -3
[ -f tools/art/apose/kerrian.png ] && echo "OK kerrian" || echo "MISSING kerrian"
